SELECT jsonb_extract_path_text(network_behavior_analytics, 'transaction_pattern_category') as pattern_cat, count(*) 
FROM riskanalysis 
GROUP BY 1 ORDER BY 2 DESC;

-- Check the full chain: transactions -> communication -> securitymonitoring -> riskanalysis -> investigation
-- Also verify how many high-risk patterns exist
SELECT count(*) as total_risk_records FROM riskanalysis;
SELECT count(*) as high_risk_count FROM riskanalysis 
WHERE jsonb_extract_path_text(network_behavior_analytics, 'transaction_pattern_category') = 'High-risk';

-- Check if there are transactions that don't have all the joins working
SELECT count(*) as total_tx FROM transactions;
SELECT count(*) as tx_with_risk FROM transactions t JOIN riskanalysis r ON t.txregistry = r.txref;
SELECT count(*) as tx_with_comm FROM transactions t JOIN communication c ON t.txregistry = c.txref;

-- Check if all transactions have communication records and security monitoring
SELECT count(*) as tx_with_comm FROM transactions t JOIN communication c ON t.txregistry = c.txref;
SELECT count(*) as comm_with_secmon FROM communication c JOIN securitymonitoring sm ON c.commregistry = sm.commref;

-- Check if there are any other columns that could be esccomprate
SELECT table_name, column_name FROM information_schema.columns 
WHERE column_name LIKE '%esc%' OR column_name LIKE '%comp%';
